window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-08bba5563c94720d"]={"versions": [{"id": "FIG-08bba5563c94720d", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs der Prüffunktion im AUTOSAR E2E-Protokoll (End-to-End Communication Protection), spezifisch für das E2E-Profil 5 (<code>E2E_P05Check</code>). Das Diagramm visualisiert den Teilschritt „Read CRC“ innerhalb des Prüfpfads empfangener E2E-geschützter Nutzdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Scope</strong>: Sub-Aktivität bzw. gekapselter Teilschritt der Funktion <code>E2E_P05Check()</code> (gekennzeichnet durch das Aufruf-Symbol / Call-Behavior-Icon).\n</li><li><strong>Aktionsknoten</strong>: <code>Copy bytes Data[Offset+0...Offset+1] using Little Endian order on 2-byte local variable ReceivedCRC</code> (Rechteck mit abgerundeten Ecken).\n</li><li><strong>Startknoten</strong>: Ausgefüllter schwarzer Kreis (Initial Node).\n</li><li><strong>Endknoten</strong>: Umrandeter ausgefüllter Kreis (Activity Final Node).\n</li><li><strong>Daten-/Variablenschnittstellen</strong>:\n<ul class=\"fig-list\"><li>Eingangsarray <code>Data[]</code> (spezifisch <code>Offset+0</code> und <code>Offset+1</code>).\n</li><li>Lokale 2-Byte-Zielvariable <code>ReceivedCRC</code> (16-Bit-Ganzzahlwert).\n</li><li>Konfigurationsparameter <code>Offset</code> zur Lokalisierung der CRC-Position im Datenstrom.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initial Node der Teilaktivität.\n</li><li>Unmittelbarer Kontrollflussübergang zur Aktion des Auslesens der Prüfsumme.\n</li><li>Ausführung der Datenextraktion: Die beiden Bytes an den Indizes <code>Offset</code> und <code>Offset + 1</code> des Datenpuffers <code>Data</code> werden in Little-Endian-Byte-Reihenfolge (LSB an <code>Offset</code>, MSB an <code>Offset + 1</code>) in die 2-Byte breite lokale Variable <code>ReceivedCRC</code> kopiert.\n</li><li>Kontrollflussübergang zum Activity Final Node und Beendigung des Teilschritts „Read CRC“.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit</strong>: Spezifiziert gemäß Anforderung <code>[PRS_E2E_00414]</code> das verpflichtende Verhalten für das Einlesen der empfangenen Prüfsumme bei Profil 5.\n</li><li><strong>Implementierungsanforderung</strong>:\n<ul class=\"fig-list\"><li>Byte-Reihenfolge: Die Auswertung muss zwingend in Little Endian erfolgen (<code>ReceivedCRC = Data[Offset] | (Data[Offset+1] &lt;&lt; 8)</code>), unabhängig von der nativen CPU-Endianness der Zielplattform.\n</li><li>Typ- und Puffergrenzen: <code>ReceivedCRC</code> ist als 16-Bit-Variable (<code>uint16</code>) auszulegen. Implementierer müssen sicherstellen, dass <code>Offset + 1</code> innerhalb der allokierten Pufferlänge von <code>Data</code> liegt, um Speicherzugriffsverletzungen zu vermeiden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-646f54a790c21792", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs der Prüffunktion im AUTOSAR E2E-Protokoll (End-to-End Communication Protection), spezifisch für das E2E-Profil 5 (<code>E2E_P05Check</code>). Das Diagramm visualisiert den Teilschritt „Read CRC“ innerhalb des Prüfpfads empfangener E2E-geschützter Nutzdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Scope</strong>: Sub-Aktivität bzw. gekapselter Teilschritt der Funktion <code>E2E_P05Check()</code> (gekennzeichnet durch das Aufruf-Symbol / Call-Behavior-Icon).\n</li><li><strong>Aktionsknoten</strong>: <code>Copy bytes Data[Offset+0...Offset+1] using Little Endian order on 2-byte local variable ReceivedCRC</code> (Rechteck mit abgerundeten Ecken).\n</li><li><strong>Startknoten</strong>: Ausgefüllter schwarzer Kreis (Initial Node).\n</li><li><strong>Endknoten</strong>: Umrandeter ausgefüllter Kreis (Activity Final Node).\n</li><li><strong>Daten-/Variablenschnittstellen</strong>:\n<ul class=\"fig-list\"><li>Eingangsarray <code>Data[]</code> (spezifisch <code>Offset+0</code> und <code>Offset+1</code>).\n</li><li>Lokale 2-Byte-Zielvariable <code>ReceivedCRC</code> (16-Bit-Ganzzahlwert).\n</li><li>Konfigurationsparameter <code>Offset</code> zur Lokalisierung der CRC-Position im Datenstrom.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initial Node der Teilaktivität.\n</li><li>Unmittelbarer Kontrollflussübergang zur Aktion des Auslesens der Prüfsumme.\n</li><li>Ausführung der Datenextraktion: Die beiden Bytes an den Indizes <code>Offset</code> und <code>Offset + 1</code> des Datenpuffers <code>Data</code> werden in Little-Endian-Byte-Reihenfolge (LSB an <code>Offset</code>, MSB an <code>Offset + 1</code>) in die 2-Byte breite lokale Variable <code>ReceivedCRC</code> kopiert.\n</li><li>Kontrollflussübergang zum Activity Final Node und Beendigung des Teilschritts „Read CRC“.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit</strong>: Spezifiziert gemäß Anforderung <code>[PRS_E2E_00414]</code> das verpflichtende Verhalten für das Einlesen der empfangenen Prüfsumme bei Profil 5.\n</li><li><strong>Implementierungsanforderung</strong>:\n<ul class=\"fig-list\"><li>Byte-Reihenfolge: Die Auswertung muss zwingend in Little Endian erfolgen (<code>ReceivedCRC = Data[Offset] | (Data[Offset+1] &lt;&lt; 8)</code>), unabhängig von der nativen CPU-Endianness der Zielplattform.\n</li><li>Typ- und Puffergrenzen: <code>ReceivedCRC</code> ist als 16-Bit-Variable (<code>uint16</code>) auszulegen. Implementierer müssen sicherstellen, dass <code>Offset + 1</code> innerhalb der allokierten Pufferlänge von <code>Data</code> liegt, um Speicherzugriffsverletzungen zu vermeiden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-08bba5563c94720d", "to": "FIG-646f54a790c21792", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
